def fusion(l1, l2):
    resultat = []
    i, j = 0, 0
    while i < len(l1) and j < len(l2):
        if l1[i] <= l2[j]:
            resultat.append(l1[i])
            i = i + 1
        else:
            resultat.append(l2[j])
            j = j + 1
    return resultat + l1[i:] + l2[j:]
